import{_ as a,o as e,c as l,aw as o}from"./chunks/framework.DLufY-ao.js";const S=JSON.parse('{"title":"HTTPS","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/network/network/http/https.md","filePath":"wiki/dev-commit/network/network/http/https.md"}'),i={name:"wiki/dev-commit/network/network/http/https.md"};function r(s,t,c,n,h,d){return e(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="https" tabindex="-1">HTTPS <a class="header-anchor" href="#https" aria-label="Permalink to &quot;HTTPS&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">HTTPS</p><ul><li><strong>HTTPS (HyperText Transfer Protocol Secure)</strong> - расширение протокола HTTP для поддержки шифрования в целях повышения безопасности. Данные в протоколе HTTPS передаются поверх криптографических протоколов SSL или TLS</li></ul></div><ul><li>Он обеспечивает защиту от атак, основанных на прослушивании сетевого соединения — от снифферских атак и атак типа man-in-the-middle, при условии, что будут использоваться шифрующие средства и сертификат сервера проверен и ему доверяют</li><li>Чтобы подготовить веб-сервер для обработки https-соединений, администратор должен получить и установить в систему сертификат открытого ключа для этого веб-сервера. В TLS используется как асимметричная схема шифрования (для выработки общего секретного ключа), так и симметричная (для обмена данными, зашифрованными общим ключом). Сертификат открытого ключа подтверждает принадлежность данного открытого ключа владельцу сайта. Сертификат открытого ключа и сам открытый ключ посылаются клиенту при установлении соединения; закрытый ключ используется для расшифровки сообщений от клиента</li></ul><h3 id="идентификация-сервера" tabindex="-1">Идентификация сервера <a class="header-anchor" href="#идентификация-сервера" aria-label="Permalink to &quot;Идентификация сервера&quot;">​</a></h3><ul><li>В начале общения, сервер посылает клиенту свой сертификат, чтобы клиент идентифицировал его. В сертификате указывается URI сервера. Если имя сервера не совпадает с указанным в сертификате, то пользовательские программы, например браузеры, сообщают об этом пользователю. В основном, браузеры предоставляют пользователю выбор: продолжить незащищённое соединение или прервать его</li></ul><h3 id="идентификация-клиента" tabindex="-1">Идентификация клиента <a class="header-anchor" href="#идентификация-клиента" aria-label="Permalink to &quot;Идентификация клиента&quot;">​</a></h3><ul><li>Обычно, сервер не располагает достаточной информацией о клиенте, для его идентификации. Однако, для обеспечения повышенной защищённости соединения используется так называемая two-way authentication. При этом сервер, после подтверждения его сертификата клиентом, также запрашивает сертификат. Таким образом, схема подтверждения клиента аналогична идентификации сервера</li></ul><h2 id="ssl-и-tls" tabindex="-1">SSL и TLS <a class="header-anchor" href="#ssl-и-tls" aria-label="Permalink to &quot;SSL и TLS&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">SSL</p><ul><li><strong>SSL</strong> (Secure Sockets Layer - уровень защищённых cокетов) — криптографический протокол, который подразумевает более безопасную связь. Он использует асимметричную криптографию для аутентификации ключей обмена, симметричное шифрование для сохранения конфиденциальности, коды аутентификации сообщений для целостности сообщений. Протокол широко использовался для обмена мгновенными сообщениями и передачи голоса через IP (англ. Voice over IP — VoIP) в таких приложениях, как электронная почта, интернет-факс и др. SSL должен быть исключён из работы в пользу TLS</li></ul></div><div class="tip custom-block"><p class="custom-block-title">TLS</p><ul><li><strong>TLS</strong> - (transport layer security - Протокол защиты транспортного уровня), как и его предшественник SSL - криптографические протоколы, обеспечивающие защищённую передачу данных между узлами в сети Интернет. TLS и SSL используют асимметричное шифрование для аутентификации, симметричное шифрование для конфиденциальности и коды аутентичности сообщений для сохранения целостности сообщений. Данный протокол широко используется в приложениях, работающих с сетью Интернет, таких как веб-браузеры, работа с электронной почтой, обмен мгновенными сообщениями и IP-телефония (VoIP)</li></ul></div><h2 id="как-работают-сертификаты" tabindex="-1">Как работают сертификаты <a class="header-anchor" href="#как-работают-сертификаты" aria-label="Permalink to &quot;Как работают сертификаты&quot;">​</a></h2><ol><li>Пользователь заходит на сайт <a href="https://www.google.com/" target="_blank" rel="noreferrer">https://www.google.com/</a> с https</li><li>Браузер скачивает сертификат с google</li><li>Каждый сертификат подписан сертификатом верхнего уровня. Когда отдают сертификат, браузер смотрит сертифкат верхнего уровня для которого смотрится также сертифкат верхнего уровня</li><li>В браузера зашиты конревые сертифкаты. И когда мы дошли по цепочке сертификатов до него, значит корректно</li></ol>',13)])])}const p=a(i,[["render",r]]);export{S as __pageData,p as default};
